import{_ as a,o as s,c as i,a3 as t}from"./chunks/framework.Cr9EE2ob.js";const k=JSON.parse(`{"title":"mdbox Alt Storage (Cold Tiering)","description":"yarilo mdbox supports moving messages to a secondary (cold) storage tier - functionally equivalent to the reference's alt-path setting and its alt-move…","frontmatter":{"head":[["meta",{"name":"robots","content":"noindex"}],["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/storage/mdbox_alt.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/main/storage/mdbox_alt.html"}],["meta",{"property":"og:title","content":"mdbox Alt Storage (Cold Tiering)"}],["meta",{"name":"twitter:title","content":"mdbox Alt Storage (Cold Tiering)"}],["meta",{"property":"og:description","content":"yarilo mdbox supports moving messages to a secondary (cold) storage tier - functionally equivalent to the reference's alt-path setting and its alt-move…"}],["meta",{"name":"twitter:description","content":"yarilo mdbox supports moving messages to a secondary (cold) storage tier - functionally equivalent to the reference's alt-path setting and its alt-move…"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/main/storage/mdbox_alt.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/main/storage/mdbox_alt.html\\",\\"headline\\":\\"mdbox Alt Storage (Cold Tiering)\\",\\"description\\":\\"yarilo mdbox supports moving messages to a secondary (cold) storage tier - functionally equivalent to the reference's alt-path setting and its alt-move…\\",\\"dateModified\\":\\"2026-10-31T12:43:41.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/main/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"mdbox Alt Storage (Cold Tiering)\\",\\"item\\":\\"https://doc.yarilomail.org/main/storage/mdbox_alt.html\\"}]}]}"]]},"headers":[],"relativePath":"storage/mdbox_alt.md","filePath":"storage/mdbox_alt.md","lastUpdated":1793450621000}`),n={name:"storage/mdbox_alt.md"};function o(l,e,r,h,d,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="mdbox-alt-storage-cold-tiering" tabindex="-1">mdbox Alt Storage (Cold Tiering) <a class="header-anchor" href="#mdbox-alt-storage-cold-tiering" aria-label="Permalink to &quot;mdbox Alt Storage (Cold Tiering)&quot;">​</a></h1><p>yarilo mdbox supports moving messages to a secondary (cold) storage tier - functionally equivalent to the reference&#39;s alt-path setting and its alt-move command. Messages moved to alt storage remain fully accessible; the Fetch path transparently falls back to the alt directory when a file is not found in primary.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">storage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mail_driver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mdbox</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mail_home</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%d/%n&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mail_alt_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/mnt/cold/%d/%n&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # &quot;&quot; = disabled (default)</span></span></code></pre></div><p><code>mail_<wbr>alt_<wbr>path</code> is a path template like <code>mail_<wbr>home</code>, with the same variables and filters - <code>%u</code>, <code>%n</code>, <code>%d</code>, <code>%h</code>, the hash buckets and the <code>%{…}</code> forms; see <a href="/main/storage/#path-templates">Path templates</a>. There is no <code>%L</code> modifier: a lowercased path is written <code>%{user | lower}</code>, and a template the server cannot expand stops startup, naming the key.</p><p>The alt directory mirrors the primary mdbox layout:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/mnt/cold/example.com/alice/</span></span>
<span class="line"><span>  storage/</span></span>
<span class="line"><span>    m.1001, m.1002, ...    ← moved m.&lt;N&gt; files (same naming scheme)</span></span></code></pre></div><p>File IDs are global across both tiers - the same <code>m.<wbr>&lt;N&gt;</code> ID never exists in both primary and alt simultaneously.</p><h2 id="helm" tabindex="-1">Helm <a class="header-anchor" href="#helm" aria-label="Permalink to &quot;Helm&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># values.yaml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">storage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mail_alt_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/mnt/cold/%d/%n&quot;</span></span></code></pre></div><p>The chart passes <code>storage.<wbr>mail_<wbr>alt_<wbr>path</code> through unchanged. The older spellings <code>mdbox_<wbr>alt_<wbr>storage_<wbr>path</code> and <code>alt_<wbr>dir</code> are pre-beta aliases of the same key.</p><p>A separate PVC (or NFS export) should be mounted at the cold path - typically a cheaper storage class (HDD-backed, object-gateway, etc.).</p><h2 id="triggering-a-move" tabindex="-1">Triggering a move <a class="header-anchor" href="#triggering-a-move" aria-label="Permalink to &quot;Triggering a move&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Move all messages older than 2025-01-01 to cold storage:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mdbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> altmove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --before</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2025-01-01T00:00:00Z</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Move all messages (no date filter):</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mdbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> altmove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice@example.com</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Move back from cold to primary (reverse):</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mdbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> altmove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --before</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2025-01-01T00:00:00Z</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --reverse</span></span></code></pre></div><p><code>--before</code> accepts RFC 3339 timestamps. Messages whose <code>InternalDate</code> (the <code>R</code> field in the dbox v2 trailer - set when the message was first saved) is strictly before the cutoff are eligible.</p><h2 id="operational-notes" tabindex="-1">Operational notes <a class="header-anchor" href="#operational-notes" aria-label="Permalink to &quot;Operational notes&quot;">​</a></h2><h3 id="fetch-transparency" tabindex="-1">Fetch transparency <a class="header-anchor" href="#fetch-transparency" aria-label="Permalink to &quot;Fetch transparency&quot;">​</a></h3><p><code>altmove</code> marks every message it relocates in the folder index, so a fetch of a moved message opens the alt file directly, without trying primary first. The IMAP client sees no difference.</p><p>The mark is a hint, not the truth. If it lags - the move finished but the index was not updated yet - a fetch that finds no primary file (<code>ENOENT</code>) tries the alt file before giving up; any other open error (permissions, I/O) is returned as-is. In the other direction, a mark whose alt copy is missing or unreadable falls back to primary rather than being reported as corruption.</p><h3 id="refcount-and-copy" tabindex="-1">Refcount and COPY <a class="header-anchor" href="#refcount-and-copy" aria-label="Permalink to &quot;Refcount and COPY&quot;">​</a></h3><p>O(1) IMAP COPY works identically across both tiers: <code>Copy()</code> only bumps the refcount; the copied map_uid continues to point at whichever tier holds the physical body. A subsequent <code>altmove</code> on the copied map_uid moves both the original and the copy together (they share the same map_uid).</p><h3 id="partial-file-moves" tabindex="-1">Partial file moves <a class="header-anchor" href="#partial-file-moves" aria-label="Permalink to &quot;Partial file moves&quot;">​</a></h3><p>When a source <code>m.<wbr>&lt;N&gt;</code> contains both eligible and ineligible records, <code>altmove</code> splits the file: eligible records go to a new alt <code>m.<wbr>&lt;N&gt;</code>, ineligible records stay in a new primary <code>m.<wbr>&lt;N&gt;</code>. Two new files are created; the old source is unlinked. The map index is updated atomically.</p><h3 id="interplay-with-purge" tabindex="-1">Interplay with Purge <a class="header-anchor" href="#interplay-with-purge" aria-label="Permalink to &quot;Interplay with Purge&quot;">​</a></h3><p>Run <code>purge</code> before <code>altmove</code> to avoid compacting zero-ref records into the alt tier unnecessarily:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mdbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> purge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice@example.com</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mdbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> altmove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --before</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2025-01-01T00:00:00Z</span></span></code></pre></div><h3 id="running-it-on-a-schedule" tabindex="-1">Running it on a schedule <a class="header-anchor" href="#running-it-on-a-schedule" aria-label="Permalink to &quot;Running it on a schedule&quot;">​</a></h3><p><code>yarctl</code> is already configured in every container of a backend pod: it carries the backend-api token and the <code>admin</code> client certificate, and, with a director, it sends each user&#39;s command to the pod that owns that user (<a href="/main/operations/yarilo_admin.html#configuration">yarctl configuration</a>). A sweep is therefore simplest run there, with the cutoff computed by the shell at run time:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># cold-tier sweep: messages older than 90 days, one user per line on stdin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">backend-po</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yarilo-backend-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  before=$(date -u -d &quot;@$(( $(date +%s) - 90*86400 ))&quot; +%Y-%m-%dT%H:%M:%SZ)</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  while read -r user; do</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    yarctl backend mdbox altmove &quot;$user&quot; --before &quot;$before&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  done&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users.txt</span></span></code></pre></div><p>Drive the user list from the passdb (the SQL <code>iterate_<wbr>query</code>, for example) and schedule the command where your other operator jobs run.</p><p>A Kubernetes CronJob of its own needs what that container already has: the backend-api URL and token, the <code>admin</code> client certificate from the <code>&lt;release&gt;-admin-internal-tls</code> Secret with its CA and server name, and the director admin URL so commands are routed by user. Without the routing, the job talks to one backend-api and becomes a second writer for every user that pod does not own.</p><h2 id="on-disk-format-and-the-reference" tabindex="-1">On-disk format and the reference <a class="header-anchor" href="#on-disk-format-and-the-reference" aria-label="Permalink to &quot;On-disk format and the reference&quot;">​</a></h2><p>A moved <code>m.<wbr>&lt;N&gt;</code> file has the same format as a primary one - the same dbox v2 record layout - and the alt tier mirrors the primary layout, so the records in it parse in either direction (<a href="/main/storage/#mdbox-on-disk-layout-rotation">mdbox on-disk layout</a>).</p><p>A store is still not interchangeable between the servers, because the index that says which message lives where is each server&#39;s own. An mdbox store of the reference is taken over by <a href="/main/installation/migration.html#adoption-this-server-takes-over-the-store-in-place">adoption</a>: on first open this server converts the index and the other server can no longer serve the store. The reverse is not possible - the reference cannot read a yarilo index.</p>`,34)])])}const m=a(n,[["render",o]]);export{k as __pageData,m as default};
